import React, { useState, useEffect, useRef } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';

// List of model filenames
const availableModels = [
  'model.obj',
  'model2.obj',
  // Add more models here
];

// Helper function to load a model
const loadModel = (modelPath) => {
  return new Promise((resolve, reject) => {
    const loader = new OBJLoader();
    loader.load(
      modelPath,
      (obj) => resolve(obj),
      undefined,
      (error) => reject(error)
    );
  });
};

const ModelLoader = ({ model, setModel, groupRef }) => {
  useEffect(() => {
    if (model) {
      const box = new THREE.Box3().setFromObject(model);
      const size = box.getSize(new THREE.Vector3());
      const maxDimension = Math.max(size.x, size.y, size.z);
      model.rotation.x = -Math.PI / 2;
      const scaleFactor = 2.5 / maxDimension;
      model.scale.set(scaleFactor, scaleFactor, scaleFactor);
      box.setFromObject(model);
      const center = box.getCenter(new THREE.Vector3());
      model.position.sub(center);

      model.traverse((child) => {
        if (child.isMesh) {
          const edges = new THREE.EdgesGeometry(child.geometry, 45);
          const lineMaterial = new THREE.LineBasicMaterial({
            color: 0xffffff,
            opacity: 0.5,
            transparent: true
          });
          const edgeLines = new THREE.LineSegments(edges, lineMaterial);
          edgeLines.position.copy(child.position);
          edgeLines.rotation.copy(child.rotation);
          edgeLines.scale.copy(child.scale);

          child.parent.add(edgeLines);
          child.parent.remove(child);
        }
      });

      if (groupRef.current) {
        groupRef.current.add(model);
      }
      setModel(model);
    }
  }, [model, setModel, groupRef]);

  return (
    <group ref={groupRef}>
      {!model && (
        <mesh>
          <boxGeometry args={[1, 1, 1]} />
          <meshBasicMaterial color="white" wireframe={true} />
        </mesh>
      )}
      {model && <primitive object={model} />}
    </group>
  );
};

const App = () => {
  const [models, setModels] = useState({});
  const [selectedModel, setSelectedModel] = useState(null);
  const [highlightedModel, setHighlightedModel] = useState(null);
  const [cameraSettings, setCameraSettings] = useState({});
  const groupRef = useRef(null);

  const { camera } = useThree();

  // Load all models when the app starts
  useEffect(() => {
    const loadAllModels = async () => {
      const modelPromises = availableModels.map((model) =>
        loadModel(`./stls/${model}`).then((loadedModel) => ({
          name: model,
          model: loadedModel,
        }))
      );

      // Wait for all models to be loaded
      const loadedModels = await Promise.all(modelPromises);
      const modelsMap = loadedModels.reduce((acc, { name, model }) => {
        acc[name] = model;
        return acc;
      }, {});

      setModels(modelsMap);
      setSelectedModel(Object.keys(modelsMap)[0]); // Set default model

      // Calculate camera settings for each model
      const newCameraSettings = {};
      loadedModels.forEach(({ name, model }) => {
        const box = new THREE.Box3().setFromObject(model);
        const size = box.getSize(new THREE.Vector3());
        const maxDimension = Math.max(size.x, size.y, size.z);
        const scaleFactor = 2.5 / maxDimension;

        // Calculate a default camera position and FOV based on model size
        const distance = scaleFactor * 3; // Adjust the distance based on model scale
        const cameraPosition = new THREE.Vector3(distance, distance, distance);
        const fov = 45; // A typical FOV value

        newCameraSettings[name] = {
          position: cameraPosition,
          fov: fov,
        };
      });

      setCameraSettings(newCameraSettings);
    };

    loadAllModels();
  }, []);

  // Handle key press for model switching
  const handleKeyPress = (event) => {
    const modelNames = Object.keys(models);
    const currentIndex = modelNames.indexOf(selectedModel);
    if (event.key === 'ArrowDown') {
      const nextIndex = (currentIndex + 1) % modelNames.length;
      setSelectedModel(modelNames[nextIndex]);
    } else if (event.key === 'ArrowUp') {
      const prevIndex = (currentIndex - 1 + modelNames.length) % modelNames.length;
      setSelectedModel(modelNames[prevIndex]);
    }
  };

  useEffect(() => {
    window.addEventListener('keydown', handleKeyPress);
    return () => {
      window.removeEventListener('keydown', handleKeyPress);
    };
  }, [selectedModel, models]);

  const handleModelClick = (model) => {
    setSelectedModel(model);
  };

  // Switch camera settings when the selected model changes
  useEffect(() => {
    if (selectedModel && cameraSettings[selectedModel]) {
      const { position, fov } = cameraSettings[selectedModel];
      camera.position.set(position.x, position.y, position.z);
      camera.fov = fov;
      camera.updateProjectionMatrix();
    }
  }, [selectedModel, camera, cameraSettings]);

  return (
    <div style={{ display: 'flex' }}>
      {/* Left Sidebar */}
      <div
        style={{
          width: '200px',
          height: '100vh',
          backgroundColor: '#333',
          padding: '20px',
          color: 'white',
          overflowY: 'auto',
        }}
      >
        <h3>Select a Model</h3>
        <ul style={{ listStyle: 'none', paddingLeft: 0 }}>
          {Object.keys(models).map((model, index) => (
            <li
              key={model}
              style={{
                padding: '10px',
                cursor: 'pointer',
                backgroundColor: selectedModel === model ? '#555' : '',
                color: selectedModel === model ? 'yellow' : 'white',
                fontWeight: highlightedModel === model ? 'bold' : 'normal',
              }}
              onClick={() => handleModelClick(model)}
              onMouseEnter={() => setHighlightedModel(model)}
              onMouseLeave={() => setHighlightedModel(null)}
            >
              {model}
            </li>
          ))}
        </ul>
      </div>

      {/* 3D Canvas */}
      <div style={{ flex: 1, height: '100vh' }}>
        <Canvas
          style={{ backgroundColor: 'black' }}
          camera={{
            position: [2.5, 2.5, 2.5],
            fov: 45,
          }}
        >
          <ambientLight intensity={0.5} />
          <spotLight position={[10, 10, 10]} intensity={1} />
          <directionalLight position={[5, 5, 5]} intensity={1} />
          {/* Render the selected pre-loaded model */}
          {selectedModel && models[selectedModel] && (
            <ModelLoader
              model={models[selectedModel]}
              setModel={(model) => models[selectedModel] = model}
              groupRef={groupRef}
            />
          )}
          <OrbitControls
            enableZoom={false}
            minPolarAngle={Math.PI / 4}
            maxPolarAngle={Math.PI / 4}
            minAzimuthAngle={-Math.PI / 4}
            maxAzimuthAngle={Math.PI / 4}
          />
        </Canvas>
      </div>
    </div>
  );
};

export default App;
